/**
 * MPLADS Anomaly Detection Data Service
 * Reads and parses data/flagged_projects.csv generated by the Python ML module.
 * Provides safe fallback to demo mock alerts if the CSV is missing or fetch fails.
 * 
 * IMPORTANT:
 * Anomaly scores and flags represent statistical outliers generated by Isolation Forest
 * for administrative prioritization. They do NOT represent proof or probabilities of fraud.
 */

import { RECENT_ANOMALY_ALERTS, MACRO_METRICS } from './mockData';

export const CSV_PATH = '/data/flagged_projects.csv';

/**
 * Robust zero-dependency CSV parser supporting quoted text with embedded commas.
 */
export function parseCSV(text) {
  if (!text || typeof text !== 'string') return [];
  const lines = text.trim().split(/\r?\n/);
  if (lines.length < 2) return [];

  function parseLine(line) {
    const cells = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        cells.push(cur.trim());
        cur = '';
      } else {
        cur += char;
      }
    }
    cells.push(cur.trim());
    return cells;
  }

  const rawHeaders = parseLine(lines[0]);
  const headers = rawHeaders.map((h) => h.replace(/^["']|["']$/g, '').trim());
  const rows = [];

  for (let i = 1; i < lines.length; i++) {
    const rawLine = lines[i].trim();
    if (!rawLine) continue;
    const values = parseLine(rawLine).map((v) => v.replace(/^["']|["']$/g, '').trim());
    
    const row = {};
    headers.forEach((h, idx) => {
      row[h] = values[idx] !== undefined ? values[idx] : '';
    });
    rows.push(row);
  }

  return rows;
}

/**
 * Derives a human-friendly severity tier based on statistical anomaly score.
 */
function deriveSeverity(score) {
  if (score >= 0.75) return 'high';
  if (score >= 0.50) return 'medium';
  return 'low';
}

/**
 * Maps raw CSV row to standard anomaly record structure used by the UI.
 */
export function mapCsvRowToAnomalyRecord(row, index) {
  const anomalyScore = parseFloat(row.anomaly_score) || 0.0;
  const isFlagged = String(row.is_flagged).toLowerCase() === 'true';
  const sanctioned = parseFloat(row.sanctioned_amount) || 0.0;
  const released = parseFloat(row.released_amount) || 0.0;
  const expenditure = parseFloat(row.expenditure_amount) || 0.0;
  const physicalProgress = parseFloat(row.physical_progress) || 0.0;
  const financialProgress = parseFloat(row.financial_progress) || 0.0;
  const progressDiscrepancy = parseFloat(row.progress_discrepancy) || 0.0;

  return {
    id: row.project_id || `ML-ANOMALY-${index + 1}`,
    workCode: row.work_code || row.project_id || `WORK-${index + 1}`,
    workTitle: row.title || 'MPLADS Scheme Record',
    district: row.district || 'Unassigned District',
    state: row.state || 'India',
    constituency: row.district ? `${row.district} Parliamentary` : 'Jurisdiction Pending',
    sector: row.sector || 'General Infrastructure',
    implementingAgency: row.implementing_agency || 'Executing Agency',
    financialYear: row.financial_year || 'FY 2024-25',
    status: row.status || 'Ongoing',
    
    // Anomaly & Model Indicators
    isFlagged: isFlagged,
    anomalyLabel: row.anomaly_label || (isFlagged ? 'Flagged (Review Required)' : 'Normal'),
    anomalyScore: Number(anomalyScore.toFixed(4)),
    modelConfidence: Number(anomalyScore.toFixed(4)), // Used by existing UI for score display
    severity: deriveSeverity(anomalyScore),
    category: row.review_category || (isFlagged ? 'Statistical Outlier' : 'Normal'),
    triggerDescription: row.review_explanation || 'Statistical deviation identified in expenditure/milestone cluster.',
    progressDiscrepancy: Number(progressDiscrepancy.toFixed(1)),
    
    // Financial Figures
    sanctionedAmountLakhs: sanctioned,
    releasedAmountLakhs: released,
    expenditureLakhs: expenditure,
    physicalProgress: physicalProgress,
    financialProgress: financialProgress,
    
    // Administrative Audit State
    detectedDate: new Date().toISOString().split('T')[0],
    auditStatus: isFlagged ? 'Pending Review' : 'Normal / No Action Needed',
    auditDisclaimer: row.audit_disclaimer || 'Flagged as statistical outlier for administrative inquiry. Requires human review. Does not imply corruption or fraud.'
  };
}

/**
 * Loads and parses flagged_projects.csv asynchronously.
 * Returns an object containing the records, computed KPIs, source metadata, and error status.
 */
export async function loadAnomalyData(csvUrl = CSV_PATH) {
  try {
    const response = await fetch(csvUrl, { cache: 'no-cache' });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status} ${response.statusText} fetching ${csvUrl}`);
    }

    const csvText = await response.text();
    const rawRows = parseCSV(csvText);

    if (!rawRows || rawRows.length === 0) {
      throw new Error('CSV file is empty or contains no parseable data rows.');
    }

    const allRecords = rawRows.map(mapCsvRowToAnomalyRecord);
    // Flagged records: rows where is_flagged is true (or highest scores first)
    const flaggedRecords = allRecords
      .filter((r) => r.isFlagged)
      .sort((a, b) => b.anomalyScore - a.anomalyScore);

    // Compute empirical KPIs from the dataset actually evaluated
    const totalEvaluated = allRecords.length;
    const flaggedCount = flaggedRecords.length;
    const normalCount = totalEvaluated - flaggedCount;
    const highSeverityCount = flaggedRecords.filter((r) => r.severity === 'high').length;
    const mediumSeverityCount = flaggedRecords.filter((r) => r.severity === 'medium').length;

    return {
      success: true,
      isDemoData: false,
      source: 'Isolation Forest Model (data/flagged_projects.csv)',
      records: flaggedRecords,
      allRecords: allRecords,
      metrics: {
        totalEvaluated,
        flaggedCount,
        normalCount,
        pendingReviews: flaggedCount,
        highSeverityCount,
        mediumSeverityCount,
        modelAlgorithm: 'Isolation Forest (Scikit-Learn)'
      },
      error: null
    };
  } catch (err) {
    console.warn(`[anomalyService] Live CSV load failed (${err.message}). Using fallback demo data.`);
    
    // Safe fallback to identified demo alerts
    return {
      success: false,
      isDemoData: true,
      source: 'Fallback Demo Data (Live ML CSV not reached)',
      records: RECENT_ANOMALY_ALERTS,
      allRecords: RECENT_ANOMALY_ALERTS,
      metrics: {
        totalEvaluated: MACRO_METRICS.totalProjects,
        flaggedCount: RECENT_ANOMALY_ALERTS.length,
        normalCount: MACRO_METRICS.totalProjects - RECENT_ANOMALY_ALERTS.length,
        pendingReviews: MACRO_METRICS.pendingAuditReviews,
        highSeverityCount: RECENT_ANOMALY_ALERTS.filter((a) => a.severity === 'high').length,
        mediumSeverityCount: RECENT_ANOMALY_ALERTS.filter((a) => a.severity === 'medium').length,
        modelAlgorithm: 'Isolation Forest (Simulation)'
      },
      error: err.message
    };
  }
}
